[CmdletBinding()]param([string]$ProjectRoot=".",[ValidateSet("initial_audit","repair_batch","final_audit")][string]$Event="repair_batch",[switch]$Apply)
$ErrorActionPreference="Stop";$Root=(Resolve-Path $ProjectRoot).Path;$Agy=Join-Path $Root ".agy";$Wi=Get-Content (Join-Path $Agy "WORK_ITEM.json") -Raw|ConvertFrom-Json;$Path=Join-Path $Agy "REPAIR_BUDGET.json";$Utf8=[Text.UTF8Encoding]::new($false)
$Mode=[string]$Wi.assurance_mode;$Defaults=if($Mode-eq"flow"){@{i=0;r=2;f=0}}else{@{i=1;r=3;f=1}};$B=if(Test-Path $Path){Get-Content $Path -Raw|ConvertFrom-Json}else{[pscustomobject]@{schema_version="1.0.0";work_item_id=$Wi.work_item_id;assurance_mode=$Mode;initial_audit_limit=$Defaults.i;repair_batch_limit=$Defaults.r;final_audit_limit=$Defaults.f;initial_audits_used=0;repair_batches_used=0;final_audits_used=0;status="available";history=@()}}
$Field=@{initial_audit="initial_audits_used";repair_batch="repair_batches_used";final_audit="final_audits_used"}[$Event];$LimitField=@{initial_audit="initial_audit_limit";repair_batch="repair_batch_limit";final_audit="final_audit_limit"}[$Event];$Next=[int]$B.$Field+1;if($Next-gt[int]$B.$LimitField){$B.status="exhausted";Write-Host "Convergence budget exhausted for $Event.";if($Apply){[IO.File]::WriteAllText($Path,($B|ConvertTo-Json -Depth 20),$Utf8)};exit 2}
$B.$Field=$Next;$B.updated_at_utc=(Get-Date).ToUniversalTime().ToString("o");$History=@($B.history)+@([pscustomobject]@{event=$Event;ordinal=$Next;at_utc=$B.updated_at_utc});$B.history=$History;if($Apply){[IO.File]::WriteAllText($Path,($B|ConvertTo-Json -Depth 20),$Utf8);Write-Host "Registered $Event $Next/$($B.$LimitField)."}else{$B|ConvertTo-Json -Depth 20}
